tasks.frontend:
// 前端：任务列表显示逾期状态
function renderTask(task) {
  let overdue = task.isOverdue ? '<span class="badge badge-danger">逾期</span>' : '';
  return `<div>${task.title} ${overdue}</div>`;
}

